// Differential checks of AssocIntOps-faithful.js against Lean, generated by leanscript --check
import * as M from "./AssocIntOps-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  return String(v);
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("test1(-7n)", () => M.test1(-7n), "-18", false);
check("test1(-1n)", () => M.test1(-1n), "6", false);
check("test1(0n)", () => M.test1(0n), "10", false);
check("test1(3n)", () => M.test1(3n), "22", false);
check("test1(12n)", () => M.test1(12n), "58", false);
check("test2(-7n)", () => M.test2(-7n), "-18", false);
check("test2(-1n)", () => M.test2(-1n), "6", false);
check("test2(0n)", () => M.test2(0n), "10", false);
check("test2(3n)", () => M.test2(3n), "22", false);
check("test2(12n)", () => M.test2(12n), "58", false);
check("test3(-7n)", () => M.test3(-7n), "-28", false);
check("test3(-1n)", () => M.test3(-1n), "20", false);
check("test3(0n)", () => M.test3(0n), "28", false);
check("test3(3n)", () => M.test3(3n), "52", false);
check("test3(12n)", () => M.test3(12n), "124", false);
check("test4(-7n)", () => M.test4(-7n), "57624", false);
check("test4(-1n)", () => M.test4(-1n), "24", false);
check("test4(0n)", () => M.test4(0n), "0", false);
check("test4(3n)", () => M.test4(3n), "1944", false);
check("test4(12n)", () => M.test4(12n), "497664", false);
check("test5(-7n)", () => M.test5(-7n), "57624", false);
check("test5(-1n)", () => M.test5(-1n), "24", false);
check("test5(0n)", () => M.test5(0n), "0", false);
check("test5(3n)", () => M.test5(3n), "1944", false);
check("test5(12n)", () => M.test5(12n), "497664", false);
check("test6(-7n)", () => M.test6(-7n), "29054597040", false);
check("test6(-1n)", () => M.test6(-1n), "5040", false);
check("test6(0n)", () => M.test6(0n), "0", false);
check("test6(3n)", () => M.test6(3n), "33067440", false);
check("test6(12n)", () => M.test6(12n), "2167107747840", false);

console.log(`AssocIntOps-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
